package com.example.TuVanSinhVien.controller;

import com.example.TuVanSinhVien.config.CustomUserDetails;
import com.example.TuVanSinhVien.entity.SinhVien;
import com.example.TuVanSinhVien.entity.TaiKhoan;
import com.example.TuVanSinhVien.repository.SinhVienRepository;
import com.example.TuVanSinhVien.repository.TaiKhoanRepository;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.time.LocalDateTime;

@Controller
public class AuthController {
    private final TaiKhoanRepository taiKhoanRepo;
    private final SinhVienRepository sinhVienRepo;
    private final PasswordEncoder passwordEncoder;

    @GetMapping("/login")
    public String loginPage(@RequestParam(required = false) String error, @RequestParam(required = false) String logout, @RequestParam(required = false) String registered, Model model) {
        if (error != null) {
            model.addAttribute("errorMessage", "Tên đăng nhập hoặc mật khẩu không chính xác, hoặc tài khoản đã bị khóa!");
        }
        if (logout != null) {
            model.addAttribute("successMessage", "Bạn đã đăng xuất khỏi hệ thống thành công.");
        }
        if (registered != null) {
            model.addAttribute("successMessage", "Đăng ký tài khoản sinh viên thành công! Mời bạn đăng nhập.");
        }
        return "auth/login";
    }

    @GetMapping("/register")
    public String registerPage() {
        return "auth/register";
    }

    @PostMapping("/register")
    public String handleRegister(@RequestParam String tenDangNhap, @RequestParam String matKhau, @RequestParam String hoTen, @RequestParam String email, @RequestParam(required = false) String soDienThoai, @RequestParam String mssv, @RequestParam String khoa, @RequestParam String nganh, @RequestParam String lop, @RequestParam String khoaHoc, RedirectAttributes redirectAttributes) {
        if (taiKhoanRepo.existsByTenDangNhap(tenDangNhap)) {
            redirectAttributes.addFlashAttribute("errorMessage", "Tên đăng nhập \'" + tenDangNhap + "\' đã tồn tại.");
            return "redirect:/register";
        }
        if (taiKhoanRepo.existsByEmail(email)) {
            redirectAttributes.addFlashAttribute("errorMessage", "Email \'" + email + "\' đã được đăng ký.");
            return "redirect:/register";
        }
        if (sinhVienRepo.existsByMssv(mssv)) {
            redirectAttributes.addFlashAttribute("errorMessage", "Mã số sinh viên (MSSV) \'" + mssv + "\' đã tồn tại trong hệ thống.");
            return "redirect:/register";
        }
        LocalDateTime now = LocalDateTime.now();
        TaiKhoan tk = TaiKhoan.builder().tenDangNhap(tenDangNhap.trim()).matKhau(passwordEncoder.encode(matKhau)).hoTen(hoTen.trim()).email(email.trim()).soDienThoai(soDienThoai != null ? soDienThoai.trim() : null).vaiTro("SinhVien").trangThai("HoatDong").batBuocDoiMatKhau(false).ngayTao(now).ngayCapNhat(now).build();
        tk = taiKhoanRepo.save(tk);
        SinhVien sv = SinhVien.builder().mssv(mssv.trim()).khoa(khoa.trim()).nganh(nganh.trim()).lop(lop.trim()).khoaHoc(khoaHoc.trim()).taiKhoan(tk).build();
        sinhVienRepo.save(sv);
        return "redirect:/login?registered=true";
    }

    @GetMapping("/profile")
    public String profilePage(@AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        if (userDetails == null) {
            return "redirect:/login";
        }
        TaiKhoan tk = taiKhoanRepo.findById(userDetails.getMaTK()).orElse(null);
        model.addAttribute("user", tk);
        if (tk != null && "SinhVien".equals(tk.getVaiTro())) {
            model.addAttribute("sinhVien", sinhVienRepo.findByTaiKhoan_MaTK(tk.getMaTK()).orElse(null));
        }
        return "auth/profile";
    }

    @PostMapping("/profile/update")
    public String updateProfile(@AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam String soDienThoai, @RequestParam String email, RedirectAttributes redirectAttributes) {
        if (userDetails == null) return "redirect:/login";
        TaiKhoan tk = taiKhoanRepo.findById(userDetails.getMaTK()).orElse(null);
        if (tk != null) {
            tk.setSoDienThoai(soDienThoai.trim());
            tk.setEmail(email.trim());
            taiKhoanRepo.save(tk);
            redirectAttributes.addFlashAttribute("successMessage", "Cập nhật thông tin liên hệ thành công!");
        }
        return "redirect:/profile";
    }

    @PostMapping("/profile/change-password")
    public String changePassword(@AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam String oldPassword, @RequestParam String newPassword, RedirectAttributes redirectAttributes) {
        if (userDetails == null) return "redirect:/login";
        TaiKhoan tk = taiKhoanRepo.findById(userDetails.getMaTK()).orElse(null);
        if (tk != null) {
            if (!passwordEncoder.matches(oldPassword, tk.getMatKhau())) {
                redirectAttributes.addFlashAttribute("errorMessage", "Mật khẩu hiện tại không chính xác!");
                return "redirect:/profile";
            }
            if (newPassword.length() < 6) {
                redirectAttributes.addFlashAttribute("errorMessage", "Mật khẩu mới phải có tối thiểu 6 ký tự!");
                return "redirect:/profile";
            }
            tk.setMatKhau(passwordEncoder.encode(newPassword));
            tk.setBatBuocDoiMatKhau(false);
            taiKhoanRepo.save(tk);
            redirectAttributes.addFlashAttribute("successMessage", "Đổi mật khẩu thành công!");
        }
        return "redirect:/profile";
    }

    @java.lang.SuppressWarnings("all")
    @lombok.Generated
    public AuthController(final TaiKhoanRepository taiKhoanRepo, final SinhVienRepository sinhVienRepo, final PasswordEncoder passwordEncoder) {
        this.taiKhoanRepo = taiKhoanRepo;
        this.sinhVienRepo = sinhVienRepo;
        this.passwordEncoder = passwordEncoder;
    }
}
